const _lazyObs=new IntersectionObserver(e=>{e.forEach(e=>{if(!e.isIntersecting)return;const s=e.target;s.dataset.src&&(s.src=s.dataset.src,s.classList.add("lazy-loaded")),_lazyObs.unobserve(s)})},{rootMargin:"300px 0px"});export function observeLazyImages(){document.querySelectorAll("img.lazy-img[data-src]").forEach(e=>_lazyObs.observe(e))}